ghg_core/gwp.py:
"""Global Warming Potential sets.

GWP values are VERSIONED, INGESTED DATA - not constants. They change between
IPCC assessment reports, and fossil vs non-fossil methane carry different
values under AR6. Recalculating under a different set creates a NEW run; it
never overwrites the old one.

Nothing in this module contains a GWP number. Load them from a published
source through `GwpSet.from_mapping` or `load_gwp_set`.
"""
from __future__ import annotations

import json
from dataclasses import dataclass, field
from decimal import Decimal
from pathlib import Path
from typing import Mapping

from .errors import GwpNotFoundError
from .quantities import D

CO2 = "CO2"
CH4_FOSSIL = "CH4_fossil"
CH4_NONFOSSIL = "CH4_nonfossil"
N2O = "N2O"


@dataclass(frozen=True)
class GwpSet:
    """One assessment report's 100-year GWP values."""
    name: str                 # e.g. "AR6"
    horizon_years: int        # 100
    source_name: str
    source_url: str
    values: Mapping[str, Decimal] = field(default_factory=dict)

    def gwp(self, gas: str) -> Decimal:
        if gas == CO2:
            return D(1)
        try:
            v = self.values[gas]
        except KeyError:
            raise GwpNotFoundError(
                f"No GWP for gas {gas!r} in set {self.name!r}. Ingest it from "
                f"{self.source_name} - do not estimate or recall a value."
            ) from None
        if v is None:
            raise GwpNotFoundError(
                f"GWP for {gas!r} in {self.name!r} is a placeholder (null). "
                f"Ingest the published value from {self.source_name}."
            )
        return D(v)

    @classmethod
    def from_mapping(cls, name, horizon_years, source_name, source_url, values):
        return cls(name, horizon_years, source_name, source_url,
                   {k: (None if v is None else D(v)) for k, v in values.items()})


def load_gwp_set(path: str | Path) -> GwpSet:
    """Load a GWP set from an ingested JSON file.

    The file must name its source. A set with no source_url is rejected,
    because an unsourced GWP is indistinguishable from an invented one.
    """
    data = json.loads(Path(path).read_text())
    for req in ("name", "horizon_years", "source_name", "source_url", "values"):
        if req not in data:
            raise ValueError(f"GWP set file is missing required key {req!r}")
    if not data["source_url"]:
        raise ValueError("A GWP set must carry a source_url.")
    return GwpSet.from_mapping(
        data["name"], data["horizon_years"],
        data["source_name"], data["source_url"], data["values"])

ghg_core/methods/agriculture/enteric.py:
"""Enteric fermentation CH4, IPCC 2006 Volume 4 Chapter 10, Tier 1.

Equation 10.19: emissions = EF for the livestock category x head count, where
the factor is kilograms of CH4 per head per year.

Cattle factors differ by region because animal size and milk yield differ; the
other species differ between developed and developing economies. Both tables
are read from `data/ipcc/enteric_fermentation.json`, which cites the page each
came from. Poultry has no Tier 1 factor at all — IPCC records insufficient data
— so asking for one raises rather than returning zero, because zero would quietly
understate an inventory that includes a poultry unit.

The result is a mass of CH4, so the report applies the chosen GWP set to it.
"""
from __future__ import annotations

import json
from dataclasses import dataclass, field
from decimal import Decimal
from pathlib import Path
from typing import Mapping, Optional

from ...quantities import D, ZERO
from ..errors import FactorNotPublished

PARAMETERS_PATH = (Path(__file__).resolve().parents[3]
                   / "data" / "ipcc" / "enteric_fermentation.json")

CATTLE_CATEGORIES = ("dairy", "other")


@dataclass(frozen=True)
class EntericParameters:
    source_name: str
    source_url: str
    read_from: str
    cattle_by_region: Mapping[str, Mapping[str, Decimal]]
    other_livestock: Mapping[str, Mapping[str, Decimal]]
    not_published: Mapping[str, str]

    @classmethod
    def load(cls, path: Path = PARAMETERS_PATH) -> "EntericParameters":
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        cattle = {
            region: {category: D(str(values[category])) for category in CATTLE_CATEGORIES}
            for region, values in data["cattle_by_region"].items()
        }
        other = {
            animal: {economy: D(str(values[economy])) for economy in ("developed", "developing")}
            for animal, values in data["other_livestock"].items()
        }
        return cls(data["source_name"], data["source_url"], data["read_from"],
                   cattle, other, data["not_published"])

    def cattle_factor(self, region: str, category: str) -> Decimal:
        if category not in CATTLE_CATEGORIES:
            raise KeyError(f"Cattle category must be 'dairy' or 'other', not {category!r}.")
        try:
            return self.cattle_by_region[region][category]
        except KeyError:
            raise KeyError(
                f"No Tier 1 cattle factor for region {region!r}. Regions in Table 10.11: "
                f"{', '.join(sorted(self.cattle_by_region))}."
            ) from None

    def livestock_factor(self, animal: str, economy: str = "developing") -> Decimal:
        if animal in self.not_published:
            raise FactorNotPublished(
                f"IPCC publishes no Tier 1 enteric factor for {animal!r}: "
                f"{self.not_published[animal]} Report this source another way rather "
                f"than treating it as zero.")
        try:
            return self.other_livestock[animal][economy]
        except KeyError:
            raise KeyError(
                f"No Tier 1 factor for {animal!r} in a {economy!r} economy. Animals in "
                f"Table 10.10: {', '.join(sorted(self.other_livestock))}."
            ) from None


@dataclass(frozen=True)
class Herd:
    """Head counts present over the year, by animal."""
    dairy_cattle: Decimal = ZERO
    other_cattle: Decimal = ZERO
    other_animals: Mapping[str, Decimal] = field(default_factory=dict)


@dataclass(frozen=True)
class EntericResult:
    ch4_kg: Decimal
    by_animal: Mapping[str, Decimal] = field(default_factory=dict)
    factors_applied: Mapping[str, Decimal] = field(default_factory=dict)


def enteric_ch4(
    herd: Herd,
    *,
    cattle_region: str = "indian_subcontinent",
    economy: str = "developing",
    parameters: Optional[EntericParameters] = None,
) -> EntericResult:
    """Annual enteric methane for a herd, in kilograms of CH4."""
    p = parameters or EntericParameters.load()
    by_animal: dict[str, Decimal] = {}
    factors: dict[str, Decimal] = {}
    total = ZERO

    for label, head, category in (("dairy_cattle", herd.dairy_cattle, "dairy"),
                                  ("other_cattle", herd.other_cattle, "other")):
        count = D(head)
        if count == ZERO:
            continue
        factor = p.cattle_factor(cattle_region, category)
        emitted = count * factor
        by_animal[label] = emitted
        factors[label] = factor
        total += emitted

    for animal, head in herd.other_animals.items():
        count = D(head)
        if count == ZERO:
            continue
        factor = p.livestock_factor(animal, economy)
        emitted = count * factor
        by_animal[animal] = emitted
        factors[animal] = factor
        total += emitted

    return EntericResult(ch4_kg=total, by_animal=by_animal, factors_applied=factors)

service/browser_api.py:
"""The calculation endpoints, without a web server, for running in the browser.

The static website (GitHub Pages) has no calculation server behind it unless
one is deployed. The browser then loads this module under Pyodide and calls
`handle` with what it would have sent over HTTP. It answers exactly as
service/app.py does for the same request, from the same ghg_core code and the
same factor tables, so a figure never depends on where it was calculated.

The AI product estimate is split in two around the one call that needs a key.
`/v1/pcf/browser-request` builds exactly the request the server would send to
the model, and `/v1/pcf/browser-assemble` validates the model's answer and
computes every figure from it with ghg_core, as the server does. The page makes
the model call in between with a key the visitor entered, which is held only
in that browser and never shipped with the site.
"""
from __future__ import annotations

import functools
import json
from types import SimpleNamespace
from typing import Any, Optional
from urllib.parse import parse_qs

from pydantic import BaseModel, TypeAdapter, ValidationError

from ghg_core import InMemoryFactorRegistry

from .catalogue import Catalogue
from .config import Settings
from .estimator import (EstimatorError, EstimatorNotAProduct, build_request, build_system,
                        build_user_message, parse_message, public_message)
from .inventory import GWP_SETS, load_gwp
from .inventory_api import (InventoryRequest, calculate_inventory, catalogue_mappings,
                            list_activities)
from .methods_api import MethodRequest, calculate_method, list_methods
from .pipeline import build_response
from .schemas import EstimateRequest

_METHOD_REQUEST = TypeAdapter(MethodRequest)

#: The model the browser asks, by default the current Opus. Same request
#: builder as the server, so only fields this model accepts are sent.
BROWSER_MODEL = "claude-opus-5-5"


@functools.lru_cache(maxsize=1)
def _pcf():
    """Settings, catalogue and (empty, as on the server) verified registry."""
    from .models import PROFILES

    settings = Settings.from_env()
    catalogue = Catalogue.load()
    registry = InMemoryFactorRegistry()
    return settings, catalogue, registry, catalogue.restricted_to(registry.activity_keys()), \
        PROFILES[BROWSER_MODEL]


def _as_attrs(value: Any) -> Any:
    """A Messages API response as JSON, readable the way the SDK object is."""
    if isinstance(value, dict):
        return SimpleNamespace(**{key: _as_attrs(item) for key, item in value.items()})
    if isinstance(value, list):
        return [_as_attrs(item) for item in value]
    return value


def _ai_error(exc: EstimatorError, assistant: str) -> tuple[int, dict]:
    return exc.status, {"detail": {"code": exc.code, "message": public_message(exc.code, assistant)}}


def _browser_request(body: Any) -> tuple[int, Any]:
    settings, _, _, prompt_catalogue, profile = _pcf()
    request = EstimateRequest.model_validate(body)
    use_beta, params = build_request(
        profile, effort=settings.effort, thinking_budget=0, max_tokens=settings.max_tokens,
        system=build_system(prompt_catalogue), user=build_user_message(request))
    return 200, {"use_beta": use_beta, "params": params, "assistant": settings.assistant_name}


def _browser_assemble(body: Any) -> tuple[int, Any]:
    settings, catalogue, registry, _, _ = _pcf()
    request = EstimateRequest.model_validate((body or {}).get("request"))
    try:
        decomposition = parse_message(_as_attrs((body or {}).get("message") or {}))
        if not decomposition.product.is_product:
            raise EstimatorNotAProduct("not a physical product or material")
    except EstimatorError as exc:
        return _ai_error(exc, settings.assistant_name)
    return 200, build_response(request, decomposition, catalogue, registry,
                               year=settings.reporting_year,
                               assistant=settings.assistant_name, cache_hit=False)


def _dump(value: Any) -> Any:
    """JSON-ready, serialised the way FastAPI serialises a response model."""
    if isinstance(value, BaseModel):
        return value.model_dump(mode="json")
    if isinstance(value, list):
        return [_dump(item) for item in value]
    return TypeAdapter(type(value)).dump_python(value, mode="json")


def _query(query: str) -> dict[str, Optional[str]]:
    return {key: values[-1] for key, values in parse_qs(query or "").items()}


def _gwp_sets() -> list[dict]:
    sets = []
    for name in GWP_SETS:
        gwp = load_gwp(name)
        sets.append({
            "name": gwp.name,
            "horizon_years": gwp.horizon_years,
            "source_name": gwp.source_name,
            "source_url": gwp.source_url,
            "gases": sorted(gwp.values),
        })
    return sets


def _route(method: str, path: str, query: dict, body: Any) -> tuple[int, Any]:
    if method == "GET" and path == "/health":
        return 200, {"status": "ok", "engine": "browser"}

    if method == "GET" and path == "/v1/inventory/activities":
        try:
            limit = int(query.get("limit") or 200)
        except ValueError:
            return 422, {"detail": "limit must be a whole number."}
        return 200, list_activities(query.get("scope"), query.get("region"),
                                    query.get("search"), max(1, min(limit, 2000)))

    if method == "GET" and path == "/v1/inventory/catalogue-map":
        return 200, catalogue_mappings()

    if method == "GET" and path == "/v1/inventory/gwp-sets":
        return 200, _gwp_sets()

    if method == "POST" and path == "/v1/inventory/calculate":
        request = InventoryRequest.model_validate(body)
        gwp = load_gwp(request.gwp_set)
        try:
            return 200, calculate_inventory(request, f"{gwp.source_name} ({gwp.source_url})")
        except ValueError as exc:
            return 422, {"detail": {"code": "unsourced_factor", "message": str(exc)}}

    if method == "GET" and path == "/v1/methods":
        return 200, list_methods()

    if method == "POST" and path == "/v1/methods/calculate":
        request = _METHOD_REQUEST.validate_python(body)
        try:
            return 200, calculate_method(request)
        except (KeyError, ValueError) as exc:
            return 422, {"detail": str(exc).strip("'")}

    if method == "POST" and path == "/v1/pcf/browser-request":
        return _browser_request(body)

    if method == "POST" and path == "/v1/pcf/browser-assemble":
        return _browser_assemble(body)

    return 404, {"detail": "Not Found"}


def handle(method: str, path: str, query: str = "", body: Optional[str] = None) -> str:
    """Answer one request. Returns JSON text: {"status": <int>, "body": <json>}."""
    try:
        payload = json.loads(body) if body else None
        status, result = _route(method.upper(), path, _query(query), payload)
    except ValidationError as exc:
        status, result = 422, {"detail": json.loads(exc.json(include_url=False))}
    except json.JSONDecodeError:
        status, result = 422, {"detail": "The request body is not valid JSON."}
    return json.dumps({"status": status, "body": _dump(result)})

service/catalogue.py:
"""The product carbon catalogue: which materials and routes IINVTY will hold
verified factors for. The AI may only map a line onto a key listed here."""
from __future__ import annotations

import csv
from dataclasses import dataclass
from pathlib import Path

from .config import REPO_ROOT

CATALOGUE_PATH = REPO_ROOT / "data" / "product_carbon_catalogue.csv"


@dataclass(frozen=True)
class CatalogueEntry:
    material_key: str
    display_name: str
    family: str
    production_route: str
    declared_unit: str
    tier_target: str


class Catalogue:
    def __init__(self, entries: list[CatalogueEntry]):
        self._by_key = {e.material_key: e for e in entries}

    @staticmethod
    def load(path: Path = CATALOGUE_PATH) -> "Catalogue":
        with path.open(encoding="utf-8", newline="") as f:
            rows = list(csv.DictReader(f))
        return Catalogue([
            CatalogueEntry(material_key=r["material_key"], display_name=r["display_name"],
                           family=r["family"], production_route=r["production_route"],
                           declared_unit=r["declared_unit"], tier_target=r["tier_target"])
            for r in rows])

    def __len__(self) -> int:
        return len(self._by_key)

    def get(self, key: str) -> CatalogueEntry | None:
        return self._by_key.get(key)

    def matches(self, key: str, route: str) -> bool:
        """A mapping counts only if the key exists AND the route agrees with it.
        A hallucinated key, or a real key with the wrong route, is ignored."""
        entry = self._by_key.get(key)
        return entry is not None and entry.production_route == route

    def restricted_to(self, keys) -> "Catalogue":
        """Only the entries whose key is in `keys`. Used to list, in the AI prompt,
        just the materials that actually have verified factors: listing the whole
        catalogue costs thousands of tokens per request and changes nothing when
        no factor exists to replace the AI's estimate."""
        wanted = set(keys)
        return Catalogue([e for k, e in self._by_key.items() if k in wanted])

    def prompt_listing(self) -> str:
        """Tier A material rows only, one per line, for the model's reference."""
        return "\n".join(
            f"{e.material_key} | route={e.production_route} | per {e.declared_unit} | {e.display_name}"
            for e in self._by_key.values() if e.tier_target == "A")

service/config.py:
"""Runtime settings, read from the environment and an optional service/.env."""
from __future__ import annotations

import os
from dataclasses import dataclass
from datetime import date
from pathlib import Path

from .models import (DEFAULT_MODELS, DEFAULT_PREMIUM_PROVIDER, DEFAULT_PROVIDER,
                     ModelProfile, get_profile)

SERVICE_DIR = Path(__file__).resolve().parent
REPO_ROOT = SERVICE_DIR.parent

ALLOWED_EFFORTS = ("low", "medium", "high", "xhigh", "max")
MIN_THINKING_BUDGET = 1024


def load_env_file(path: Path | None = None) -> None:
    """Minimal KEY=VALUE loader. Never overrides a variable already set, so a
    real environment always wins over the file.

    PCF_ENV_FILE overrides the location; set it to an empty string to load no
    file at all. The test suite does that so it never reads local secrets.
    """
    if path is None:
        override = os.environ.get("PCF_ENV_FILE")
        if override == "":
            return
        path = Path(override) if override else SERVICE_DIR / ".env"
    if not path.exists():
        return
    for raw in path.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, _, value = line.partition("=")
        value = value.split(" #", 1)[0]          # allow trailing comments
        key, value = key.strip(), value.strip().strip('"').strip("'")
        if key and value and key not in os.environ:
            os.environ[key] = value


def gemini_api_key() -> str:
    return (os.environ.get("GEMINI_API_KEY") or os.environ.get("GOOGLE_API_KEY") or "").strip()


def ai_credentials_present(provider: str = "anthropic") -> bool:
    """True when the selected provider has something to authenticate with.

    Anthropic: an API key, an auth token, or an `ant auth login` profile.
    Gemini: GEMINI_API_KEY (or GOOGLE_API_KEY).
    Never reads a secret's value beyond checking it is non-empty.
    """
    if provider == "gemini":
        return bool(gemini_api_key())
    if os.environ.get("ANTHROPIC_API_KEY") or os.environ.get("ANTHROPIC_AUTH_TOKEN"):
        return True
    if os.environ.get("ANTHROPIC_PROFILE"):
        return True
    return (Path.home() / ".config" / "anthropic").is_dir()


def parse_provider_chain(raw: str) -> list[ModelProfile]:
    """PCF_AI_PROVIDER, tried in order. Each entry is `provider` or
    `provider:model`, e.g. gemini:gemini-3.8-flash,gemini:gemini-3.6-flash,anthropic.

    A bare provider uses PCF_<PROVIDER>_MODEL, else its default model.
    PCF_AI_MODEL still works when the chain has a single bare entry.
    """
    entries = [e.strip() for e in raw.split(",") if e.strip()]
    if not entries:
        raise ValueError("PCF_AI_PROVIDER is empty. Set it to e.g. gemini or gemini,anthropic.")
    profiles: list[ModelProfile] = []
    for entry in entries:
        provider, _, model = (part.strip() for part in entry.partition(":"))
        provider = provider.lower()
        if not model:
            model = os.environ.get(f"PCF_{provider.upper()}_MODEL", "").strip()
        if not model and len(entries) == 1:
            model = os.environ.get("PCF_AI_MODEL", "").strip()
        profile = get_profile(model or DEFAULT_MODELS.get(provider, ""), provider)
        if profile in profiles:
            raise ValueError(f"PCF_AI_PROVIDER lists {profile.provider}:{profile.model} twice.")
        profiles.append(profile)
    return profiles


def _int(name: str, default: int) -> int:
    raw = os.environ.get(name, "").strip()
    try:
        return int(raw) if raw else default
    except ValueError:
        raise ValueError(f"{name} must be a whole number, got {raw!r}") from None


@dataclass(frozen=True)
class Settings:
    profiles: tuple[ModelProfile, ...]        # free plan, in the order tried
    premium_profiles: tuple[ModelProfile, ...]  # what an upgrade actually buys
    effort: str
    thinking_budget: int          # Haiku only; 0 = thinking off
    max_tokens: int
    cors_origins: tuple[str, ...]
    reporting_year: int
    cache_ttl_seconds: int        # 0 = cache off
    cache_path: Path
    rate_limit_per_hour: int      # 0 = unlimited
    assistant_name: str           # the only AI name the public ever sees
    admin_token: str              # guards /admin/status; empty disables it

    @property
    def profile(self) -> ModelProfile:
        """The primary provider: tried first."""
        return self.profiles[0]

    @property
    def model(self) -> str:
        return self.profile.model

    @property
    def provider(self) -> str:
        return self.profile.provider

    @property
    def cache_identity(self) -> str:
        """The provider chain, for cache keys. A single provider keeps the plain
        model name, so existing cached answers stay valid."""
        return ">".join(p.model for p in self.profiles)

    @property
    def premium_cache_identity(self) -> str:
        """Premium answers are cached apart from free ones.

        They come from a different model and are the thing the customer paid
        for. Sharing one key would serve a paying customer the cheap answer
        whenever a free visitor had asked about the same product first.
        """
        return ">".join(p.model for p in self.premium_profiles)

    def cache_identity_for(self, premium: bool) -> str:
        return self.premium_cache_identity if premium else self.cache_identity

    @staticmethod
    def from_env() -> "Settings":
        profiles = parse_provider_chain(os.environ.get("PCF_AI_PROVIDER", DEFAULT_PROVIDER))

        # What Premium buys. The free plan runs on whatever is cheapest that
        # answers; a paying customer gets the model that reasons hardest about
        # a lifecycle, with the free chain behind it so an Anthropic outage
        # degrades the answer instead of removing it.
        premium_raw = os.environ.get("PCF_AI_PROVIDER_PREMIUM", DEFAULT_PREMIUM_PROVIDER)
        premium_profiles = parse_provider_chain(premium_raw)
        for profile in profiles:
            if profile not in premium_profiles:
                premium_profiles.append(profile)

        effort = os.environ.get("PCF_AI_EFFORT", "high").strip().lower()
        if effort not in ALLOWED_EFFORTS:
            raise ValueError(f"PCF_AI_EFFORT must be one of {ALLOWED_EFFORTS}, got {effort!r}")

        max_tokens = _int("PCF_AI_MAX_TOKENS", 16000)
        thinking_budget = _int("PCF_AI_THINKING_BUDGET", 0)
        if thinking_budget and not (MIN_THINKING_BUDGET <= thinking_budget < max_tokens):
            raise ValueError(
                f"PCF_AI_THINKING_BUDGET must be 0 (off) or between {MIN_THINKING_BUDGET} "
                f"and PCF_AI_MAX_TOKENS ({max_tokens}), got {thinking_budget}")

        origins = os.environ.get("PCF_CORS_ORIGINS", "http://localhost:5173")
        return Settings(
            profiles=tuple(profiles),
            premium_profiles=tuple(premium_profiles),
            effort=effort,
            thinking_budget=thinking_budget,
            max_tokens=max_tokens,
            cors_origins=tuple(o.strip() for o in origins.split(",") if o.strip()),
            reporting_year=_int("PCF_REPORTING_YEAR", date.today().year),
            cache_ttl_seconds=_int("PCF_CACHE_TTL_DAYS", 30) * 86400,
            cache_path=Path(os.environ.get("PCF_CACHE_PATH",
                                           str(SERVICE_DIR / "data" / "estimate_cache.db"))),
            rate_limit_per_hour=_int("PCF_RATE_LIMIT_PER_HOUR", 30),
            assistant_name=os.environ.get("PCF_ASSISTANT_NAME", "INSITY EDGE AI").strip()
            or "INSITY EDGE AI",
            admin_token=os.environ.get("PCF_ADMIN_TOKEN", "").strip(),
        )

